from ._tulis import Q, bab, kursus, latihan

# ---------------------------------------------------------------- 3 System Administrator
kursus(3, "System Administrator",
 bab(["Menjelaskan tugas administrator sistem Linux: akun pengguna, izin berkas, layanan, jadwal, dan cadangan.",
      "Membaca izin berkas dalam bentuk simbolik dan oktal.",
      "Menjelaskan perintah dasar systemctl untuk mengelola layanan.",
      "Menjelaskan aturan cadangan 3-2-1."],
  ("Pekerjaan administrator sistem",
   "Pekerjaan administrator sistem berpusat pada menjaga server tetap berjalan dengan aman. Bahan belajar bab ini dibatasi pada hal yang bisa dibaca di manual resmi: membuat akun pengguna (useradd), mengatur izin berkas (chmod), mengelola layanan (systemctl), menjadwalkan tugas (crontab), mengamankan akses SSH, dan membuat cadangan. Semua perintah di bab ini sebaiknya kamu coba di mesin virtual milikmu sendiri, bukan di server yang dipakai orang lain, karena beberapa perintah dapat mengubah akses dan menghapus data."),
  ("Izin berkas dengan chmod",
   "Manual chmod menjelaskan dua cara menulis izin. Mode simbolik berbentuk [ugoa][+-=][rwx]: u adalah pemilik, g grup, o pengguna lain, dan a semuanya; + menambah bit, - menghapusnya, dan = mengatur persis yang disebutkan. Mode numerik memakai angka oktal: 4 untuk baca (r), 2 untuk tulis (w), dan 1 untuk eksekusi (x), dijumlahkan; digit pertama untuk pemilik, kedua untuk grup, ketiga untuk lainnya. Jadi 755 berarti pemilik rwx, grup r-x, lainnya r-x, dan 644 berarti pemilik rw-, grup dan lainnya r--. Untuk direktori, x berarti izin 'mencari' di dalamnya."),
  ("Layanan, jadwal, dan cadangan",
   "Manual systemctl: start mengaktifkan unit sekarang, stop menonaktifkannya, restart memulai ulang (atau memulai bila belum berjalan), reload meminta unit memuat ulang konfigurasinya sendiri, enable membuat symlink agar unit terhubung (misalnya jalan saat boot) tanpa menjalankannya sekarang kecuali dengan --now, disable membalikkannya, dan status menampilkan status runtime ringkas dan baris jurnal terbaru. Aturan cadangan 3-2-1 menurut Nakivo: tiga salinan data (data asli ditambah dua cadangan), dua jenis media penyimpanan berbeda, dan satu salinan di luar lokasi.")),
 bab(["Membuat akun dan grup dengan useradd serta memahami file yang terlibat.",
      "Menjelaskan opsi useradd -G, -s, -d, dan -g.",
      "Menentukan izin yang tepat untuk skenario sederhana.",
      "Menjelaskan arti bit khusus pada chmod."],
  ("Akun pengguna dengan useradd",
   "Manual useradd: perintah ini membuat akun pengguna baru memakai opsi yang diberikan dan nilai bawaan sistem. Opsi -G menambahkan pengguna ke grup tambahan (daftar dipisah koma tanpa spasi), -s menetapkan shell login, -d menetapkan direktori rumah, dan -g menetapkan grup utama yang harus sudah ada. Berkas yang terkait: /etc/passwd (informasi akun), /etc/shadow (informasi akun yang aman), dan /etc/group (informasi grup). Sebuah grup dibuat untuk tiap pengguna kecuali opsi -n dipakai."),
  ("Bit khusus dan contoh izin",
   "Manual chmod: pada mode numerik, digit keempat (paling depan) mengatur bit khusus: 4 untuk setuid, 2 untuk setgid, dan 1 untuk sticky. Sticky bit pada direktori mencegah pengguna tanpa hak istimewa menghapus atau mengganti nama berkas yang bukan miliknya. Contoh dari manual: chmod u+x skrip.sh menambah izin eksekusi untuk pemilik; chmod go-w catatan.txt menghapus izin tulis untuk grup dan lainnya; chmod a=r laporan.pdf membuat semua orang hanya bisa membaca.")),
 bab(["Menulis entri crontab dengan lima kolom waktu.",
      "Memakai string khusus seperti @daily dan @reboot.",
      "Menjelaskan perbedaan reload dan restart.",
      "Menjelaskan perbedaan enable dan start."],
  ("Crontab",
   "Manual crontab(5): tiap baris perintah punya lima kolom waktu lalu perintah. Kolom: menit (0-59), jam (0-23), tanggal (0-31), bulan (0-12 atau nama), dan hari dalam pekan (0-7, 0 dan 7 adalah Minggu). Tanda * berarti semua nilai, 8-11 adalah rentang, 1,2,5,9 adalah daftar, dan */2 adalah langkah tiap dua. Contoh dari manual: '5 0 * * *' menjalankan perintah lima menit setelah tengah malam setiap hari; '15 14 1 * *' menjalankan pukul 14.15 pada tanggal 1 tiap bulan. String khusus: @reboot, @yearly, @monthly, @weekly, @daily, dan @hourly."),
  ("Mengelola layanan dengan benar",
   "Dari manual systemctl: enable dan start berbeda. enable hanya menghubungkan unit sesuai bagian [Install] dan tidak menjalankannya sekarang kecuali memakai --now; start menjalankannya sekarang tetapi tidak membuatnya otomatis jalan saat boot. reload hanya meminta layanan memuat ulang konfigurasinya, sedangkan restart menghentikan lalu memulai layanan lagi. status dipakai untuk membaca keadaan layanan; is-active memberi kode keluar 0 bila unit aktif.")),
 bab(["Membaca parameter keamanan SSH (Port, PermitRootLogin, PasswordAuthentication).",
      "Menjelaskan risiko memberi izin yang terlalu longgar.",
      "Menjelaskan varian aturan cadangan 3-2-1-1 dan 3-2-1-1-0.",
      "Merencanakan cadangan dan pengujian pemulihan sederhana."],
  ("Konfigurasi SSH",
   "Tabel parameter sshd_config dari artikel Linux Journal (artikel lama, tetapi parameternya masih dikenal): Port menentukan port TCP yang didengarkan sshd, bawaan 22. PermitRootLogin mengatur apakah root boleh login langsung; tabel itu menyarankan 'No' sehingga administrator masuk dengan akun biasa lalu memakai su. PasswordAuthentication mengatur login dengan nama pengguna dan kata sandi (bawaan yes); mematikannya mengharuskan autentikasi berbasis kunci. PermitEmptyPasswords bawaannya no. Selalu cocokkan nilai bawaan dengan versi OpenSSH yang kamu pakai karena artikel itu lama."),
  ("Cadangan lebih ketat",
   "Menurut Nakivo, varian 3-2-1-1 menambahkan satu salinan yang immutable atau air-gapped. Salinan immutable memakai penyimpanan write-once-read-many sehingga tidak dapat diubah atau dihapus; air-gapped disimpan offline dan terputus dari produksi. Varian 3-2-1-1-0 menambahkan tujuan nol kesalahan saat pemulihan, yang berarti cadangan juga perlu diuji dengan benar-benar memulihkannya.")),
 bab(["Menerapkan semua materi pada skenario server kecil sekolah.",
      "Memilih izin, jadwal, dan layanan yang tepat untuk skenario.",
      "Menyusun rencana cadangan yang memenuhi 3-2-1.",
      "Menulis catatan kerja yang bisa diperiksa."],
  ("Skenario: server berkas sekolah",
   "Sebuah server berkas sekolah ingin: (1) akun guru baru, (2) folder materi yang bisa dibaca semua tetapi hanya bisa diubah pemilik, (3) tugas menyalin data tiap hari pukul 02.00, dan (4) layanan web yang hidup otomatis saat boot. Jawaban berdasarkan manual: (1) useradd dengan -m, -G, dan -s sesuai kebutuhan; (2) chmod 755 untuk folder dan 644 untuk berkas; (3) crontab '0 2 * * *' diikuti perintah salin; (4) systemctl enable --now nama-layanan."),
  ("Skenario: rencana cadangan",
   "Server berkas berisi data penting. Rencana 3-2-1: data asli di server, satu cadangan di hard disk eksternal (media berbeda), satu cadangan di tempat lain (offsite). Tambahkan uji pemulihan berkala untuk mendekati tujuan 'nol kesalahan' pada varian 3-2-1-1-0. Catat setiap perintah yang dijalankan, tanggalnya, dan hasilnya agar orang lain dapat memeriksa pekerjaanmu.")),
 {"title": "Server Linux kecil dengan akun, izin, jadwal, dan cadangan",
  "brief": "Di mesin virtual Linux milikmu sendiri, siapkan sebuah server kecil. Buat tiga akun dengan grup berbeda, atur izin folder bersama dengan chmod, jalankan satu layanan memakai systemctl (enable dan start), jadwalkan satu tugas cadangan dengan crontab, dan lakukan cadangan serta pemulihan sesuai prinsip 3-2-1. Dokumentasikan setiap langkah beserta rujukan manualnya.",
  "criteria": ["Tiga akun dengan grup yang berbeda dan bukti perintah useradd serta isi /etc/passwd (tanpa menampilkan kata sandi).",
               "Folder bersama dengan izin yang dijelaskan dalam bentuk oktal dan simbolik.",
               "Satu layanan dikelola dengan systemctl (status sebelum dan sesudah enable/start).",
               "Satu entri crontab dengan penjelasan lima kolom waktunya.",
               "Cadangan yang memenuhi 3-2-1 (jelaskan tiap salinan) dan bukti uji pemulihan.",
               "Konfigurasi SSH: sebutkan nilai Port, PermitRootLogin, PasswordAuthentication dan alasannya.",
               "Daftar sumber manual yang dipakai dan pernyataan bahwa semua dikerjakan di mesin milikmu sendiri."]},
 [
 Q(2, "A", "Pada mode oktal chmod, angka 4 berarti izin:", "Baca (r)", "Tulis (w)", "Eksekusi (x)", "Hapus", "a", "Manual chmod: 4 untuk baca, 2 untuk tulis, 1 untuk eksekusi."),
 Q(2, "K", "Izin 755 berarti:", "Pemilik rwx, grup r-x, lainnya r-x", "Pemilik rw-, grup r--, lainnya r--", "Semua rwx", "Pemilik r-x, grup rwx, lainnya ---", "a", "7 = 4+2+1 (rwx); 5 = 4+1 (r-x)."),
 Q(2, "K", "Izin 644 berarti:", "Pemilik rw-, grup r--, lainnya r--", "Pemilik rwx, grup r-x, lainnya r-x", "Semua r--", "Semua rw-", "a", "6 = 4+2 (rw-), sedangkan 4 = r-- untuk grup dan lainnya."),
 Q(2, "K", "Perintah chmod u+x skrip.sh melakukan:", "Menambah izin eksekusi untuk pemilik", "Menghapus semua izin", "Mengubah pemilik berkas", "Menyalin berkas", "a", "u adalah pemilik, + menambah bit, x adalah eksekusi."),
 Q(2, "K", "Cadangan 3-2-1 menurut Nakivo berarti:", "Tiga salinan, dua jenis media, satu salinan di luar lokasi", "Tiga disk, dua server, dan satu kabel yang dipakai bersama", "Tiga hari, dua minggu, dan satu bulan jadwal cadangan", "Tiga akun, dua grup, dan satu pengguna yang berhak", "a", "Itu definisi aturan 3-2-1."),
 Q(2, "K", "systemctl enable berbeda dari start karena enable:", "Menghubungkan unit sesuai bagian [Install] tanpa menjalankannya sekarang kecuali --now", "Menjalankan layanan saat itu juga tanpa memengaruhi keadaan setelah reboot", "Menghapus layanan dari sistem sehingga tidak muncul lagi dalam daftar unit", "Menampilkan log terbaru dari layanan tanpa mengubah status unit sama sekali", "a", "Manual: enable membuat symlink dan tidak menjalankan unit kecuali dengan --now."),
 Q(2, "A", "Perintah systemctl untuk menjalankan layanan sekarang:", "start", "enable", "disable", "mask", "a", "start mengaktifkan unit sekarang."),
 Q(3, "K", "Berkas /etc/shadow menurut manual useradd berisi:", "Informasi akun pengguna yang aman", "Daftar printer yang tersambung ke sistem tersebut", "Log sistem yang dicatat oleh layanan journald", "Konfigurasi layanan SSH yang dipakai oleh server", "a", "Manual menyebut /etc/shadow sebagai informasi akun yang aman."),
 Q(3, "K", "Opsi useradd untuk menambahkan pengguna ke grup tambahan:", "-G", "-s", "-d", "-m", "a", "-G menambahkan pengguna ke grup tambahan, dipisah koma tanpa spasi."),
 Q(3, "K", "Opsi useradd -s dipakai untuk:", "Menetapkan shell login", "Menetapkan grup", "Menetapkan direktori rumah", "Menghapus akun", "a", "Opsi -s menetapkan shell login."),
 Q(3, "K", "Sticky bit pada direktori berfungsi:", "Mencegah pengguna tanpa hak istimewa menghapus atau mengganti nama berkas yang bukan miliknya", "Mempercepat akses disk dengan menyimpan isi direktori itu di memori utama", "Menyembunyikan seluruh berkas di direktori itu dari pengguna selain pemiliknya", "Mengenkripsi seluruh isi direktori sehingga hanya root yang dapat membacanya", "a", "Manual chmod menjelaskan fungsi restricted deletion/sticky pada direktori."),
 Q(3, "K", "Pada mode oktal empat digit, digit paling depan mengatur:", "Bit khusus (setuid, setgid, sticky)", "Izin untuk pemilik berkas dalam mode tiga digit", "Izin untuk grup pemilik berkas dalam mode tiga digit", "Izin untuk pengguna lain dalam mode tiga digit", "a", "Manual: digit pertama 4=setuid, 2=setgid, 1=sticky."),
 Q(3, "K", "Perintah chmod go-w catatan.txt:", "Menghapus izin tulis untuk grup dan lainnya", "Menambah izin tulis untuk semua", "Mengubah pemilik", "Menghapus berkas", "a", "g dan o adalah grup dan lainnya, - menghapus bit, w adalah tulis."),
 Q(3, "A", "Berkas yang menyimpan informasi akun dasar pengguna Linux:", "/etc/passwd", "/etc/hosts", "/var/log", "/tmp", "a", "Manual useradd menyebut /etc/passwd sebagai informasi akun pengguna."),
 Q(4, "K", "Entri crontab '5 0 * * *' menjalankan perintah:", "Lima menit setelah tengah malam setiap hari", "Setiap lima jam sekali sepanjang hari tanpa memandang tanggal", "Setiap lima hari sekali pada jam yang sama sepanjang bulan", "Lima kali dalam sehari pada jam yang terbagi sama rata", "a", "Manual crontab: contoh itu berarti lima menit setelah tengah malam, setiap hari."),
 Q(4, "K", "Entri crontab '15 14 1 * *' menjalankan perintah:", "Pukul 14.15 pada tanggal 1 tiap bulan", "Pukul 15.14 tiap hari", "Tiap 15 menit", "Pada 1 Januari saja", "a", "Menit 15, jam 14, tanggal 1, setiap bulan."),
 Q(4, "K", "Kolom keempat pada lima kolom waktu crontab adalah:", "Bulan", "Jam", "Menit", "Hari dalam pekan", "a", "Urutan: menit, jam, tanggal, bulan, hari dalam pekan."),
 Q(4, "K", "String khusus crontab untuk dijalankan sekali sehari:", "@daily", "@reboot", "@hourly", "@weekly", "a", "@daily (atau @midnight) berarti sekali sehari."),
 Q(4, "K", "Perbedaan restart dan reload pada systemctl:", "restart menghentikan lalu memulai layanan; reload hanya meminta layanan memuat ulang konfigurasinya", "Keduanya sama persis dan hanya berbeda penulisan perintah pada berbagai distribusi", "reload menghapus layanan dari sistem lalu memasangnya kembali dari paket asli", "restart hanya menampilkan status layanan tanpa mengubah proses yang sedang berjalan", "a", "Manual: reload meminta unit memuat ulang konfigurasinya sendiri."),
 Q(4, "A", "Kode keluar perintah systemctl is-active bila unit aktif adalah:", "0", "1", "-1", "99", "a", "Manual: keluar 0 bila setidaknya satu unit aktif."),
 Q(4, "K", "systemctl disable:", "Menghapus symlink yang dibuat enable tetapi tidak menghentikan layanan kecuali --now", "Menghapus berkas program layanan dari disk sehingga tidak dapat dipasang ulang", "Menghapus akun pengguna yang menjalankan layanan beserta seluruh berkas miliknya", "Memformat disk tempat berkas konfigurasi layanan itu tersimpan di server", "a", "Manual: disable membalikkan enable dan tidak menghentikan unit kecuali --now atau stop."),
 Q(5, "K", "Menurut tabel parameter sshd_config, PermitRootLogin sebaiknya diatur:", "No, agar admin masuk dengan akun biasa lalu memakai su", "Yes, supaya admin bisa langsung masuk sebagai root dari jaringan mana pun", "Tidak perlu diatur karena nilainya tidak pernah dibaca oleh sshd", "Sama dengan nilai Port supaya konfigurasi lebih mudah diingat admin", "a", "Tabel Linux Journal menyarankan nilai 'No'."),
 Q(5, "K", "Port bawaan sshd menurut tabel parameter itu adalah:", "22", "80", "443", "3306", "a", "Port TCP bawaan sshd adalah 22."),
 Q(5, "K", "Mematikan PasswordAuthentication mengharuskan:", "Autentikasi berbasis kunci", "Tanpa autentikasi", "Login anonim", "Port 80", "a", "Tabel: mematikannya mengharuskan autentikasi berbasis kunci."),
 Q(5, "K", "Cadangan 3-2-1-1 menambahkan:", "Satu salinan immutable atau air-gapped", "Satu monitor cadangan untuk memeriksa status pekerjaan cadangan", "Satu kabel cadangan untuk menghubungkan server ke penyimpanan", "Satu printer cadangan untuk mencetak laporan hasil pencadangan", "a", "Menurut Nakivo, salinan itu tidak dapat diubah atau terputus dari produksi."),
 Q(5, "K", "Tujuan 'nol' pada 3-2-1-1-0 adalah:", "Nol kesalahan saat pemulihan cadangan", "Nol salinan cadangan yang disimpan di luar lokasi utama", "Nol pengguna yang boleh membaca isi media cadangan", "Nol catatan log yang dibuat selama proses pencadangan", "a", "Nakivo: tujuan nol kesalahan pada pemulihan cadangan."),
 Q(5, "K", "Agar layanan web hidup otomatis saat boot dan langsung berjalan sekarang, perintah yang sesuai:", "systemctl enable --now nama-layanan", "systemctl disable nama-layanan", "systemctl status", "chmod 777", "a", "enable membuat unit terhubung saat boot dan --now menjalankannya sekarang."),
 Q(5, "A", "Cadangan di hard disk eksternal dan satu di tempat lain, selain data asli, memenuhi:", "Aturan 3-2-1", "Aturan 1-1-1", "Aturan 0-0-0", "Tidak ada aturan", "a", "Tiga salinan, dua jenis media, satu offsite."),
 ],
 sumber=[("Manual chmod (Debian)", "https://manpages.debian.org/buster/coreutils/chmod.1"),
         ("Manual crontab(5) (Debian)", "https://manpages.debian.org/trixie/cron/crontab.5.en.html"),
         ("Manual systemctl (Debian)", "https://manpages.debian.org/jessie-backports/systemd/systemctl.1.en.html"),
         ("Manual useradd(8)", "https://mirror.ircam.fr/pub/planetccrma/man/man8/useradd.8.html"),
         ("Nakivo: 3-2-1 Backup Rule", "https://www.nakivo.com/blog/3-2-1-backup-rule/"),
         ("Linux Journal: parameter sshd_config (artikel lama)", "https://www.linuxjournal.com/files/linuxjournal.com/linuxjournal/articles/044/4412/4412t2.html")])
latihan(3,
 ["Di VM Linux milikmu, buat file dan ubah izinnya dengan chmod 644, 755, dan 600; catat hasil ls -l setiap kali.",
  "Tulis tabel konversi simbolik ke oktal untuk lima izin yang berbeda.",
  "Baca manual chmod dan tulis arti bit setuid, setgid, dan sticky dengan bahasamu."],
 ["Buat akun uji dengan useradd memakai opsi -m, -G, dan -s, lalu lihat barisnya di /etc/passwd (jangan tampilkan hash).",
  "Tulis perbedaan -g dan -G dalam useradd dengan contohmu sendiri.",
  "Buat folder bersama untuk satu grup dan uji siapa yang bisa membaca dan menulis."],
 ["Tulis lima entri crontab dengan jadwal berbeda dan jelaskan lima kolomnya.",
  "Buat unit sederhana atau pakai layanan yang sudah ada dan coba start, stop, status, enable.",
  "Tulis perbedaan reload dan restart beserta kapan kamu memilih masing-masing."],
 ["Buat skrip cadangan sederhana dan jadwalkan dengan crontab di VM, lalu uji pemulihan.",
  "Tulis rencana 3-2-1 untuk data sekolah fiktif dengan lokasi dan media tiap salinan.",
  "Tulis catatan hardening SSH untuk VM-mu (Port, PermitRootLogin, PasswordAuthentication) dengan alasanmu."])
